# GPUShaderCreateInfo equivalent for merged.glsl (generated by SLASL; do not edit).
import gpu
from gpu.types import GPUShaderCreateInfo, GPUStageInterfaceInfo

VERTEX_OUT = GPUStageInterfaceInfo("StageInterface")
VERTEX_OUT.smooth("vec2", "v_uv")

info = GPUShaderCreateInfo()
info.vertex_in(0, "vec3", "position")
info.vertex_in(1, "vec2", "uv")
info.vertex_out(VERTEX_OUT)
info.fragment_out(0, "vec4", "frag_color")
info.uniform_buf(0, "Camera")
info.uniform_buf(1, "Params")
info.sampler(0, "sampler2D", "tex")
info.vertex_source("merged.glsl")
info.fragment_source("merged.glsl")

shader = gpu.shader.create_from_info(info)
